        '\u8fd9\u4e2a', '\u8fd9\u9053\u6570\u5b66\u9898', 'Bonjour', 'hola', 'hallo'
    ]
    is_non_english = any(ind in task_content for ind in non_english_indicators)

    # Initialize agents
    reasoning_agents = [LLMAgentBase(['thinking', 'answer', 'confidence'], 'Reasoning Agent', temperature=0.6) for _ in range(6)]
