    cross_lingual_agent = LLMAgentBase(['thinking', 'answer', 'confidence'], 'Cross-Lingual Agent', temperature=0.6)

    # Store all paths: (thinking_info, answer_info, confidence_score, verification_passed)
    all_paths = []

    # Step 1: Generate multiple reasoning paths
    for i in range(len(reasoning_agents)):
        try:
            thinking, answer, confidence = reasoning_agents[i]([taskInfo], cot_instruction, i)

            # Parse confidence score safely
            try:
                conf = int(confidence.content.strip())
            except (ValueError, AttributeError):
                conf = 50

            all_paths.append((thinking, answer, conf, False))
        except Exception:
            continue

    # Step 2: Verify top confidence paths only
    if len(all_paths) > 0:
        all_paths.sort(key=lambda x: x[2], reverse=True)
        top_paths = all_paths[:min(3, len(all_paths))]

        for idx, (thinking, answer, conf, _) in enumerate(top_paths):
            try:
                thinking_v, verified = verification_agent([taskInfo, thinking, answer], verification_instruction, idx + 100)

                verified_content = verified.content.lower() if verified and verified.content else ''
                passed = 'verified' in verified_content or 'true' in verified_content

                all_paths[idx] = (thinking, answer, conf, passed)
            except Exception:
                continue

    # Step 3: Cross-lingual verification for non-English problems
    if is_non_english:
        try:
            trans_thinking, trans_answer, trans_confidence = cross_lingual_agent([taskInfo], cross_lingual_instruction, len(all_paths) + 1)

            try:
                trans_conf = int(trans_confidence.content.strip())
            except (ValueError, AttributeError):
                trans_conf = 50

            all_paths.append((trans_thinking, trans_answer, trans_conf, True))

            # Boost confidence for paths matching translation
            for idx, (thinking, answer, conf, passed) in enumerate(all_paths):
                if idx < len(all_paths) - 1 and answer.content == trans_answer.content:
                    all_paths[idx] = (thinking, answer, min(conf + 10, 100), passed)
        except Exception:
            pass

    # Step 4: Weighted voting with verification bonus
    answers_dict = {}
    for thinking, answer, conf, passed in all_paths:
        answer_content = answer.content
        weight = conf
        if passed:
            weight = weight * 1.3

        if answer_content not in answers_dict:
            answers_dict[answer_content] = {'score': 0, 'count': 0, 'verified_count': 0}
        answers_dict[answer_content]['score'] += weight
        answers_dict[answer_content]['count'] += 1
        if passed:
            answers_dict[answer_content]['verified_count'] += 1

    # Calculate best answer with weighted voting
    best_answer = None
    best_weighted_score = -1

    for answer_content, data in answers_dict.items():
        consensus_bonus = 1.1 if data['count'] > 1 else 1.0
        verification_bonus = 1.2 if data['verified_count'] > 0 else 1.0
        weighted_score = data['score'] * consensus_bonus * verification_bonus

        if weighted_score > best_weighted_score:
            best_weighted_score = weighted_score
            best_answer = answer_content

    # Return the answer Info object that matches the best weighted answer
    if best_answer and all_paths:
        for thinking, answer, conf, passed in all_paths:
            if answer.content == best_answer:
                return answer

    # Fallback: return the answer from the highest scoring path
    if all_paths:
        all_paths.sort(key=lambda x: x[2], reverse=True)
        return all_paths[0][1]

    # Ultimate fallback: return any generated answer
    if len(all_paths) > 0:
        return all_paths[0][1]

    # If all else fails, try one more reasoning attempt
    try:
        thinking, answer, _ = reasoning_agents[0]([taskInfo], cot_instruction, 999)
        return answer
    except Exception:
        return None

