    for i, agent in enumerate(debate_agents):
        try:
            output = agent([taskInfo], initial_cot_instruction, i)

            if len(output) >= 3:
                thinking = output[0]
                answer = output[1]
                confidence = output[2]

                # Parse confidence score safely
                try:
                    conf = int(confidence.content.strip()) if confidence and confidence.content else 50
                except (ValueError, AttributeError):
