                all_paths.append((thinking, answer, conf, False))
        except Exception:
            continue

    # Step 2: Second debate round - agents see others' answers and refine
    if len(all_paths) >= 2:
        for i, agent in enumerate(debate_agents):
            if i >= len(all_paths):
                continue

            try:
                # Include task and all previous answers for context
                input_infos = [taskInfo] + [path[1] for path in all_paths]
