        LLMAgentBase(['thinking', 'answer', 'confidence'], 'Analyst', temperature=0.5),
    ]

    step_verifier = LLMAgentBase(['thinking', 'step_verification'], 'Step Verifier', temperature=0.3)
    error_classifier = LLMAgentBase(['thinking', 'error_types'], 'Error Classifier', temperature=0.4)
    step_corrector = LLMAgentBase(['thinking', 'answer', 'confidence'], 'Step Corrector', temperature=0.4)
    cross_lingual_agent = LLMAgentBase(['thinking', 'answer', 'confidence'], 'Cross-Lingual Agent', temperature=0.6)
    final_decision_agent = LLMAgentBase(['thinking', 'answer'], 'Final Decision Agent', temperature=0.1)

    # Storage: (thinking_info, answer_info, confidence, step_verified, error_types, is_cross_lingual)
    all_paths = []

    # Step 1: Initial reasoning round - all agents generate answers with numbered steps
    for i, agent in enumerate(reasoning_agents):
        try:
            output = agent([taskInfo], initial_instruction, i)
            if len(output) >= 3:
                thinking = output[0]
                answer = output[1]
                confidence = output[2]

                try:
                    conf = int(confidence.content.strip()) if confidence else 50
                except (ValueError, AttributeError):
                    conf = 50

                # Default verification status
                all_paths.append((thinking, answer, conf, 'unverified', '', False))
        except Exception:
            continue

    # Step 2: Step-level verification on all paths
    for idx in range(len(all_paths)):
        thinking, answer, conf, step_ver, error_types, is_cross = all_paths[idx]
        try:
            verify_output = step_verifier([taskInfo, thinking, answer], step_verify_instruction, len(reasoning_agents) + idx + 1)
            if len(verify_output) >= 2:
                verify_info = verify_output[1]
                verify_content = verify_info.content.lower() if verify_info else ''
                step_ver = verify_content if 'all_verified' in verify_content or 'some_errors' in verify_content or 'many_errors' in verify_content else 'unverified'
                all_paths[idx] = (thinking, answer, conf, step_ver, error_types, is_cross)
        except Exception:
