    # Step 3: Error type classification for paths with errors (not all_verified)
    for idx in range(len(all_paths)):
        thinking, answer, conf, step_ver, error_types, is_cross = all_paths[idx]
        if step_ver != 'all_verified':
            try:
                error_output = error_classifier([taskInfo, thinking, answer], error_type_instruction, len(reasoning_agents) + len(all_paths) + idx + 1)
                if len(error_output) >= 2:
                    error_info = error_output[1]
                    error_content = error_info.content if error_info else ''
                    all_paths[idx] = (thinking, answer, conf, step_ver, error_content, is_cross)
            except Exception:
