    # Step 4: Generate corrected paths for paths with errors
    corrected_paths = []
    for idx, (thinking, answer, conf, step_ver, error_types, is_cross) in enumerate(all_paths):
        # Only correct paths that have errors (not all_verified)
        if step_ver != 'all_verified':
            try:
                correct_output = step_corrector([taskInfo, thinking, answer, error_types], correction_instruction, len(all_paths) + idx + 1)
                if len(correct_output) >= 3:
                    corr_thinking = correct_output[0]
                    corr_answer = correct_output[1]
                    corr_confidence = correct_output[2]
                    try:
                        corr_conf = int(corr_confidence.content.strip()) if corr_confidence else 50
                    except (ValueError, AttributeError):
                        corr_conf = 50
                    # Corrected paths start with verified status (since we just corrected them)
                    corrected_paths.append((corr_thinking, corr_answer, corr_conf, 'all_verified', 'known', False))
            except Exception:
                # If correction fails, keep original path
                corrected_paths.append((thinking, answer, conf, step_ver, error_types, is_cross))
        else:
            # Already verified, no correction needed
            corrected_paths.append((thinking, answer, conf, step_ver, error_types, is_cross))

    all_paths = corrected_paths

    # Step 5: Cross-lingual verification for non-English problems only
    cross_lingual_path = None
    if is_non_english and len(all_paths) >= 2:
        try:
            trans_output = cross_lingual_agent([taskInfo], cross_lingual_instruction, len(all_paths) + 1)
            if len(trans_output) >= 3:
                trans_thinking = trans_output[0]
                trans_answer = trans_output[1]
                trans_confidence = trans_output[2]
                try:
                    trans_conf = int(trans_confidence.content.strip()) if trans_confidence else 50
                except (ValueError, AttributeError):
                    trans_conf = 50
