        thinking, answer, conf, step_ver, error_types, is_cross = all_paths[cross_idx]
        try:
            verify_output = step_verifier([taskInfo, thinking, answer], step_verify_instruction, len(all_paths) + 1)
            if len(verify_output) >= 2:
                verify_info = verify_output[1]
                verify_content = verify_info.content.lower() if verify_info else ''
                step_ver = verify_content if 'all_verified' in verify_content or 'some_errors' in verify_content or 'many_errors' in verify_content else 'unverified'
                all_paths[cross_idx] = (thinking, answer, conf, step_ver, error_types, is_cross)
        except Exception:
            pass

        # Find matching paths and boost them
        for idx in range(len(all_paths) - 1):
            if all_paths[idx][1].content == cross_lingual_path[1].content:
                thinking, answer, conf, step_ver, error_types, is_cross = all_paths[idx]
                all_paths[idx] = (thinking, answer, min(conf + 15, 100), 'all_verified', 'known', True)

    # Step 7: Confidence-weighted voting with verification bonuses
    answers_dict = {}
    for thinking, answer, conf, step_ver, error_types, is_cross in all_paths:
        answer_content = answer.content

        # Base weight from confidence
        weight = conf

        # Step verification bonuses (based on verification result)
        if step_ver == 'all_verified':
            weight = weight * 1.4
        elif step_ver == 'some_errors':
            weight = weight * 1.1

        # Known error types bonus (meaning we identified and addressed them)
        if error_types == 'known':
            weight = weight * 1.2

        # Cross-lingual bonus
        if is_cross:
            weight = weight * 1.15

        if answer_content not in answers_dict:
            answers_dict[answer_content] = {'score': 0, 'count': 0, 'verified_count': 0}

        answers_dict[answer_content]['score'] += weight
        answers_dict[answer_content]['count'] += 1
        if step_ver == 'all_verified':
            answers_dict[answer_content]['verified_count'] += 1

    # Step 8: Final decision consolidation using top candidates
    if len(answers_dict) > 0:
        top_answers = sorted(answers_dict.keys(), key=lambda x: answers_dict[x]['score'], reverse=True)[:3]

        top_answer_infos = []
        for answer_content in top_answers:
            for thinking, answer, conf, step_ver, error_types, is_cross in all_paths:
                if answer.content == answer_content:
                    top_answer_infos.append(answer)
                    break
            if len(top_answer_infos) >= 3:
                break

        if len(top_answer_infos) >= 2:
            final_decision_input = [taskInfo] + top_answer_infos
            try:
                final_output = final_decision_agent(final_decision_input, final_decision_instruction, 999)
                if len(final_output) >= 2:
                    thinking = final_output[0]
                    answer = final_output[1]
                    return answer
            except Exception:
                pass

    # Step 9: Fallback - confidence-weighted voting
    if len(answers_dict) > 0:
        best_answer = max(answers_dict.keys(), key=lambda x: answers_dict[x]['score'])
        for thinking, answer, conf, step_ver, error_types, is_cross in all_paths:
            if answer.content == best_answer:
                return answer

    # Step 10: Unified fallback - must always return Info object
    for agent in reasoning_agents:
        try:
            output = agent([taskInfo], initial_instruction, 9999)
            if len(output) >= 3:
                return output[1]
        except Exception:
            continue

    if len(all_paths) > 0:
        all_paths.sort(key=lambda x: x[2], reverse=True)
        return all_paths[0][1]

    # Step 11: Final fallback with safety check
    try:
        output = reasoning_agents[0]([taskInfo], initial_instruction, 100000)
        if len(output) >= 3:
            return output[1]
    except Exception:
        pass

    # Absolute last resort
    return reasoning_agents[0]([taskInfo], initial_instruction, 100001)[1]

def forward(self, taskInfo):
    from collections import Counter

