        '\u8fd9\u4e2a' in task_content or '\u8fd9\u9053\u6570\u5b66\u9898' in task_content,
        'bonjour' in task_content_lower,
        'hola' in task_content_lower,
        'hallo' in task_content_lower,
        ' le ' in task_content_lower,
        ' el ' in task_content_lower,
        ' der ' in task_content_lower,
        ' das ' in task_content_lower,
        ' una ' in task_content_lower,
        ' un ' in task_content_lower
    ])

    # Initialize agents
    reasoning_agents = [
        LLMAgentBase(['thinking', 'answer', 'confidence', 'evidence'], 'Mathematician', temperature=0.7),
        LLMAgentBase(['thinking', 'answer', 'confidence', 'evidence'], 'Problem Solver', temperature=0.8),
        LLMAgentBase(['thinking', 'answer', 'confidence', 'evidence'], 'Logical Thinker', temperature=0.6),
        LLMAgentBase(['thinking', 'answer', 'confidence', 'evidence'], 'Analyst', temperature=0.5),
    ]

    basic_verifier = LLMAgentBase(['thinking', 'basic_status'], 'Basic Verifier', temperature=0.3)
    full_verifier = LLMAgentBase(['thinking', 'verification_status'], 'Full Verifier', temperature=0.3)
    calibrator = LLMAgentBase(['thinking', 'calibrated_confidence'], 'Confidence Calibrator', temperature=0.4)
    cross_lingual_agent = LLMAgentBase(['thinking', 'answer', 'confidence'], 'Cross-Lingual Agent', temperature=0.6)
    final_decision_agent = LLMAgentBase(['thinking', 'answer'], 'Final Decision Agent', temperature=0.1)

    # Storage: (thinking_info, answer_info, confidence, evidence_quality, basic_verified, full_verified, calibrated_confidence, is_cross_lingual)
    all_paths = []
    avg_conf = 50  # Default value

    # Step 1: Initial reasoning with evidence citation
    for i, agent in enumerate(reasoning_agents):
        try:
            output = agent([taskInfo], initial_instruction, i)
            if len(output) >= 4:
                thinking = output[0]
                answer = output[1]
                confidence = output[2]
                evidence = output[3]

                try:
                    conf = int(confidence.content.strip()) if confidence else 50
                except (ValueError, AttributeError):
                    conf = 50

                # Evidence quality (0-1 based on whether evidence is cited)
                evidence_quality = 1.0 if (evidence and evidence.content) else 0.5

                all_paths.append((thinking, answer, conf, evidence_quality, False, False, conf, False))
        except Exception:
            continue

    # Step 2: Calculate initial confidence variance for adaptive verification
    if len(all_paths) >= 2:
        confidences = [p[2] for p in all_paths]
        avg_conf = sum(confidences) / len(confidences)
        confidence_variance = sum((c - avg_conf) ** 2 for c in confidences) / len(confidences)
    else:
        confidence_variance = 0

    # Step 3: Tiered verification based on initial confidence
    low_conf_threshold = 70
    for idx in range(len(all_paths)):
        thinking, answer, conf, evid_quality, basic_ver, full_ver, cal_conf, is_cross = all_paths[idx]

        # Tier 1: Basic verification for high confidence paths
        if conf >= low_conf_threshold:
            try:
                basic_output = basic_verifier([taskInfo, thinking, answer], basic_verify_instruction, len(reasoning_agents) + idx + 1)
                if len(basic_output) >= 2:
                    basic_info = basic_output[1]
                    basic_content = basic_info.content.lower() if basic_info else ''
                    basic_ver = 'consistent' in basic_content and 'inconsistent' not in basic_content
                    all_paths[idx] = (thinking, answer, conf, evid_quality, basic_ver, full_ver, cal_conf, is_cross)
            except Exception:
                continue

        # Tier 2: Full verification for low confidence paths or all if variance is high
        elif confidence_variance > 150 or not basic_ver:
            try:
                full_output = full_verifier([taskInfo, thinking, answer], full_verify_instruction, len(reasoning_agents) + len(all_paths) + idx + 1)
                if len(full_output) >= 2:
                    full_info = full_output[1]
                    full_content = full_info.content.lower() if full_info else ''
                    if 'fully_verified' in full_content:
                        full_ver = True
                    elif 'partial_errors' in full_content:
                        full_ver = False
                all_paths[idx] = (thinking, answer, conf, evid_quality, basic_ver, full_ver, cal_conf, is_cross)
            except Exception:
                continue

    # Step 4: Bayesian-style confidence calibration for all paths
    for idx in range(len(all_paths)):
        thinking, answer, conf, evid_quality, basic_ver, full_ver, cal_conf, is_cross = all_paths[idx]

        try:
            cal_output = calibrator([taskInfo, thinking, answer], confidence_calibrate_instruction, len(reasoning_agents) + len(all_paths) + idx + 1)
            if len(cal_output) >= 2:
                cal_info = cal_output[1]
                try:
                    cal_conf = int(cal_info.content.strip()) if cal_info else conf
                except (ValueError, AttributeError):
                    cal_conf = conf

                # Bayesian update: weighted average of original and calibrated confidence
                # Weight calibration by verification quality
                ver_weight = 0.3
                if basic_ver and full_ver:
                    ver_weight = 0.7
                elif basic_ver or full_ver:
                    ver_weight = 0.5
                elif evid_quality >= 0.8:
                    ver_weight = 0.4

                calibrated_conf = int(conf * (1 - ver_weight) + cal_conf * ver_weight)
                all_paths[idx] = (thinking, answer, conf, evid_quality, basic_ver, full_ver, calibrated_conf, is_cross)
        except Exception:
            continue

    # Step 5: Adaptive cross-lingual verification based on consensus
    unique_answers = set([p[1].content for p in all_paths])

    # Only do cross-lingual if there's disagreement or non-English with low consensus
    do_cross_lingual = (len(unique_answers) > 2) or (is_non_english and avg_conf < 75)

    if do_cross_lingual and len(all_paths) >= 2:
        try:
            trans_output = cross_lingual_agent([taskInfo], cross_lingual_instruction, len(all_paths) + 1)
            if len(trans_output) >= 3:
                trans_thinking = trans_output[0]
                trans_answer = trans_output[1]
                trans_confidence = trans_output[2]
                try:
                    trans_conf = int(trans_confidence.content.strip()) if trans_confidence else 50
                except (ValueError, AttributeError):
                    trans_conf = 50

                # Cross-lingual path starts unverified
                all_paths.append((trans_thinking, trans_answer, trans_conf, 0.5, False, False, trans_conf, True))
        except Exception:
            pass

    # Step 6: Path pruning - remove very low confidence paths
    min_confidence_threshold = 40
    all_paths = [p for p in all_paths if p[6] >= min_confidence_threshold]

    # Step 7: Hierarchical voting with verification-based weights
    answers_dict = {}
    for thinking, answer, conf, evid_quality, basic_ver, full_ver, cal_conf, is_cross in all_paths:
        answer_content = answer.content

        # Base weight from calibrated confidence
        weight = cal_conf

        # Verification bonuses (hierarchical)
        if full_ver:
            weight = weight * 1.4
        elif basic_ver:
            weight = weight * 1.2

        # Evidence quality bonus
        weight = weight * evid_quality

        # Cross-lingual tiebreaker bonus
        if is_cross:
            weight = weight * 1.1

        if answer_content not in answers_dict:
            answers_dict[answer_content] = {'score': 0, 'count': 0, 'full_verified_count': 0}

        answers_dict[answer_content]['score'] += weight
        answers_dict[answer_content]['count'] += 1
        if full_ver:
            answers_dict[answer_content]['full_verified_count'] += 1

    # Step 8: Final decision consolidation
    if len(answers_dict) > 0:
        # Get top 3 answers
        top_answers = sorted(answers_dict.keys(), key=lambda x: answers_dict[x]['score'], reverse=True)[:3]

        top_answer_infos = []
        for answer_content in top_answers:
            for thinking, answer, conf, evid_quality, basic_ver, full_ver, cal_conf, is_cross in all_paths:
                if answer.content == answer_content:
                    top_answer_infos.append(answer)
                    break
            if len(top_answer_infos) >= 3:
                break

        if len(top_answer_infos) >= 2:
            final_decision_input = [taskInfo] + top_answer_infos
            try:
                final_output = final_decision_agent(final_decision_input, final_decision_instruction, 999)
                if len(final_output) >= 2:
                    thinking = final_output[0]
                    answer = final_output[1]
                    return answer
            except Exception:
                pass

    # Step 9: Fallback - hierarchical voting
    if len(answers_dict) > 0:
        best_answer = max(answers_dict.keys(), key=lambda x: answers_dict[x]['score'])
        for thinking, answer, conf, evid_quality, basic_ver, full_ver, cal_conf, is_cross in all_paths:
            if answer.content == best_answer:
                return answer

    # Step 10: Unified fallback - must always return Info object
    for agent in reasoning_agents:
        try:
            output = agent([taskInfo], initial_instruction, 9999)
            if len(output) >= 3:
                return output[1]
        except Exception:
            continue

    if len(all_paths) > 0:
        all_paths.sort(key=lambda x: x[6], reverse=True)  # Sort by calibrated confidence
        return all_paths[0][1]

