    try:
        output = reasoning_agents[0]([taskInfo], initial_instruction, 100000)
        if len(output) >= 3:
            return output[1]
    except Exception:
        pass

    # Absolute last resort with safety
    try:
        output = reasoning_agents[0]([taskInfo], initial_instruction, 100001)
        if len(output) >= 3:
            return output[1]
    except Exception:
        pass

    # Final fallback - must return something valid
    return reasoning_agents[0]([taskInfo], initial_instruction, 100002)[1]

def forward(self, taskInfo):
    from collections import Counter

    # Instructions for different stages
    initial_instruction = 'Solve this mathematical problem step by step. Explicitly state each calculation in the format "Step N: [value] [op] [value] = [result]". Assess confidence (0-100).'

    trace_alignment_instruction = 'Compare the numerical calculation traces from two reasoning paths. Check if the final results match and intermediate numbers are consistent. Output "aligned" if both calculations lead to the same result with consistent numbers, "misaligned" otherwise.'

