        LLMAgentBase(['thinking', 'answer', 'confidence', 'trace'], 'Logical Thinker', temperature=0.6),
        LLMAgentBase(['thinking', 'answer', 'confidence', 'trace'], 'Analyst', temperature=0.5),
    ]

    cross_lingual_agent = LLMAgentBase(['thinking_en', 'answer_en', 'confidence', 'trace_en'], 'Cross-Lingual Agent', temperature=0.6)
    alignment_agent = LLMAgentBase(['alignment_status'], 'Trace Alignment Verifier', temperature=0.3)
    final_decision_agent = LLMAgentBase(['answer'], 'Final Decision Agent', temperature=0.1)

    # Storage: (thinking_info, answer_info, confidence_score, trace_info, is_aligned, is_cross_lingual)
    all_paths = []

    # Step 1: Initial reasoning round - all agents generate answers with numerical traces
    for i, agent in enumerate(perspective_agents):
        try:
            output = agent([taskInfo], initial_instruction, i)
            if len(output) >= 4:
                thinking = output[0]
                answer = output[1]
                confidence = output[2]
                trace = output[3]

                try:
                    conf = int(confidence.content.strip()) if confidence and confidence.content else 50
                except (ValueError, AttributeError):
                    conf = 50

                all_paths.append((thinking, answer, conf, trace, False, False))
        except Exception:
            continue

    # Step 2: Cross-lingual generation with alignment check (only once)
    cross_lingual_path = None
    if len(all_paths) >= 2:
        try:
            trans_output = cross_lingual_agent([taskInfo], cross_lingual_instruction, len(all_paths) + 1)

            if len(trans_output) >= 4:
