                # Alignment check between best source path and cross-lingual path
                if all_paths:
                    # Sort by confidence to get best source path for comparison
                    all_paths.sort(key=lambda x: x[2], reverse=True)
                    best_source_trace = all_paths[0][3]
                    best_source_thinking = all_paths[0][0]

                    try:
                        align_output = alignment_agent([taskInfo, best_source_thinking, best_source_trace, trans_thinking, trans_trace], trace_alignment_instruction, len(all_paths) + 2)
                        if len(align_output) >= 1:
