                            # Mark both source and cross-lingual as aligned if consistent
                            is_aligned = 'aligned' in align_content and 'misaligned' not in align_content

                            # Update the best source path
                            best_thinking = all_paths[0][0]
                            best_answer = all_paths[0][1]
